import Foundation

public enum FinderFileTemplate: String, CaseIterable, Sendable {
    case text
    case markdown
    case word
    case excel
    case powerpoint

    public var pathExtension: String {
        switch self {
        case .text: "txt"
        case .markdown: "md"
        case .word: "docx"
        case .excel: "xlsx"
        case .powerpoint: "pptx"
        }
    }

    public var data: Data {
        switch self {
        case .text, .markdown:
            Data()
        case .word:
            Self.decode(Self.wordTemplate)
        case .excel:
            Self.decode(Self.excelTemplate)
        case .powerpoint:
            Self.decode(Self.powerpointTemplate)
        }
    }

    private static func decode(_ value: String) -> Data {
        Data(base64Encoded: value, options: .ignoreUnknownCharacters) ?? Data()
    }

    // Minimal, self-generated OOXML packages. They intentionally contain no
    // third-party document templates or application-specific metadata.
    private static let wordTemplate = """
    
    """

    private static let excelTemplate = """
    
    """

    private static let powerpointTemplate = """
    
    """
}

public enum FinderFileCreator {
    public static func create(
        template: FinderFileTemplate,
        baseName: String,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> URL {
        let directory = directory.standardizedFileURL.resolvingSymlinksInPath()
        guard FinderTargetResolver.isDirectory(directory, fileManager: fileManager) else {
            throw FinderFileCreationError.invalidDirectory
        }

        for suffix in 1...10_000 {
            let numberedName = suffix == 1 ? baseName : "\(baseName) \(suffix)"
            let destination = directory
                .appendingPathComponent(numberedName)
                .appendingPathExtension(template.pathExtension)
            do {
                try template.data.write(to: destination, options: .withoutOverwriting)
                return destination
            } catch let error as CocoaError where error.code == .fileWriteFileExists {
                continue
            }
        }
        throw FinderFileCreationError.tooManyConflicts
    }
}

public enum FinderFileCreationError: Error, Equatable {
    case invalidDirectory
    case tooManyConflicts
}
